CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY, path TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY, title TEXT NOT NULL, content TEXT, image_url TEXT, category TEXT, published INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sellers (id SERIAL PRIMARY KEY, name TEXT NOT NULL, bio TEXT, image_url TEXT, verified INTEGER DEFAULT 0, location TEXT, contact_email TEXT, rating DOUBLE PRECISION DEFAULT 5, total_sales INTEGER DEFAULT 0, member_since TEXT, featured INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS razes (id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT, image_url TEXT, card_name TEXT, card_year TEXT, card_grade TEXT, sport TEXT, seller_id INTEGER, seller_name TEXT, estimated_value DOUBLE PRECISION, entry_price DOUBLE PRECISION, max_entries INTEGER DEFAULT 100, sold_entries INTEGER DEFAULT 0, total_tickets INTEGER DEFAULT 0, status TEXT DEFAULT 'upcoming', starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, winner_user_id INTEGER, winner_name TEXT, draw_seed TEXT, draw_proof TEXT, drawn_at TIMESTAMPTZ, featured INTEGER DEFAULT 0, published INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS raze_entries (id SERIAL PRIMARY KEY, raze_id INTEGER, user_id INTEGER, user_name TEXT, user_email TEXT, quantity INTEGER DEFAULT 1, amount DOUBLE PRECISION, payment_status TEXT DEFAULT 'pending', etransfer_ref TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS card_submissions (id SERIAL PRIMARY KEY, user_id INTEGER, submitter_name TEXT, submitter_email TEXT, card_name TEXT, card_year TEXT, card_grade TEXT, sport TEXT, description TEXT, image_url TEXT, asking_price DOUBLE PRECISION, status TEXT DEFAULT 'pending', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reviews (id SERIAL PRIMARY KEY, seller_id INTEGER, author_name TEXT, rating INTEGER DEFAULT 5, content TEXT, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS winners (id SERIAL PRIMARY KEY, raze_id INTEGER, raze_title TEXT, winner_name TEXT, card_name TEXT, image_url TEXT, draw_date TIMESTAMPTZ DEFAULT NOW(), draw_proof TEXT, total_tickets INTEGER, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY, from_user_id INTEGER, from_name TEXT, to_user_id INTEGER, to_name TEXT, raze_id INTEGER, body TEXT, read INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS form_submissions (id SERIAL PRIMARY KEY, name TEXT, email TEXT, subject TEXT, message TEXT, created_at TIMESTAMPTZ DEFAULT NOW());